SELECT /*selectSellerMpDsFertiPckmtrlList*/ '1' AS NUM , 'RE14000023 ' AS A , '00001' AS B , '20140213' AS C , '123123' AS D , 'EA' AS E , '0' AS F , '' AS G , '' AS H , '구매담당자' AS I , '견적의뢰' AS J , '123' AS K , '20140220' AS L , '123123' AS M , '1' AS N , '0' AS O , '' AS P , '구매팀' AS Q , 'KRKEPB0004' AS R , '1' AS S , 'KRBEST0003' AS T , '(주)오피스디포코리아' AS U , 'KEP200470' AS V , '김미경' AS W , '' AS Y FROM DUAL WHERE 1=1
AND A.QUOTATION_NO LIKE '%'||#{st_quotation_no}||'%'
AND A.BTOA_USER_DEPT = #{st_btoa_user_dept_code}
AND A.BUYER_ITEM_NO = #{st_search_code}
AND A.DESCRIPTION LIKE '%'||#{st_search_code}||'%'
AND A.SPECIFICATION LIKE '%'||#{st_search_code}||'%'
AND J LIKE '%'||#{st_sourcing_status}||'%'
AND A.BTOA_USER_ID = #{st_user_id}
AND A.RECV_FLAG ^='GD'

